      company_name: lead.company,
    });
    console.log(`[ChatBridge] Upgraded legacy lead #${lead.id} → session #${session.id}[${session.session_code}]`);
    await this.relayMessageAcrossBridge(message, session, 'desk_to_customer', body);
    return true;
  } catch (err) {
    console.error('[ChatBridge] Legacy upgrade failed:', err.message);
  }
  return false;
}

