/**
 * Two-way live relay between customer and company desk.
 * Returns true if the message was consumed by the bridge (including close).
 */
async handleChatBridge(message, phone, chatId, body) {
  const digits = this.formatPhone(phone);
  if (!digits) return false;

  const session = ChatSessions.findActiveByEitherPhone(digits);
  if (!session) {
    // Legacy fallback: one-way quote relay via submissions.quote_relay_active
    return this.tryRelayDeskQuote(message, phone, chatId, body);
  }

  const isCustomer = session.customer_phone === digits;
  const isDesk = session.desk_phone === digits;
  if (!isCustomer && !isDesk) return false;

  // Close command (customer or desk)
  if (body && isCloseCommand(body)) {
    await this.closeChatSession(session, {
      closedBy: isCustomer ? 'customer' : 'desk',
      replyTo: message,
      chatId,
    });
    return true;
  }

  if (isDesk) {
    ChatSessions.touch(session.id, { desk_chat_id: chatId });
    await this.relayMessageAcrossBridge(message, session, 'desk_to_customer', body);
    return true;
  }

  // Customer side: do not steal greeting/Yes/No away from a brand-new flow
  // while they already have a bridge — relay everything except close (handled above).
  // If they say Hi while bridged, still relay to desk (they must close first to restart).
  ChatSessions.touch(session.id, { customer_chat_id: chatId });
  await this.relayMessageAcrossBridge(message, session, 'customer_to_desk', body);
  return true;
}

